<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Branch,Company,Customer,CustomerContact,InventoryBalance,ProductVariant,SalesOrder,SalesOrderItem,SalesOrderStatusHistory,StockReservation,Warehouse,WarehouseLocation};
use App\Services\AuthorizationService;
use App\Support\{Decimal,TenantContext};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

final class SalesOrderController
{
 private function tenant():string{return app(TenantContext::class)->id();}
 private function authorize(Request $r,string $permission,?SalesOrder $o=null):void{$t=$this->tenant();abort_unless($r->user()&&app(AuthorizationService::class)->allows($r->user(),$t,$permission,$o?->company_id,$o?->branch_id),403);if($o)abort_unless($o->tenant_id===$t,404);}
 private function scope(array $d,Request $r):void{$t=$this->tenant();abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),404);abort_unless(app(AuthorizationService::class)->allows($r->user(),$t,'sales.manage',$d['company_id'],$d['branch_id']??null),403);if(!empty($d['branch_id']))abort_unless(Branch::where('tenant_id',$t)->whereKey($d['branch_id'])->where('company_id',$d['company_id'])->exists(),404);}
 private function history(SalesOrder $o,?string $from,string $to,Request $r,string $field='state',?string $reason=null):void{SalesOrderStatusHistory::create(['tenant_id'=>$o->tenant_id,'sales_order_id'=>$o->id,'actor_id'=>$r->user()->id,'field'=>$field,'from_value'=>$from,'to_value'=>$to,'reason'=>$reason]);}
 private function query(Request $r){$q=SalesOrder::where('tenant_id',$this->tenant())->with(['customer','quotation','items.variant.product']);if($r->filled('company_id'))$q->where('company_id',$r->string('company_id'));if($r->filled('branch_id'))$q->where('branch_id',$r->string('branch_id'));if($r->filled('state'))$q->where('state',$r->string('state'));if($r->filled('reservation_status'))$q->where('reservation_status',$r->string('reservation_status'));if($r->filled('search'))$q->where(fn($x)=>$x->where('number','ilike','%'.$r->string('search').'%')->orWhereHas('customer',fn($c)=>$c->where('name','ilike','%'.$r->string('search').'%')));if($r->filled('date_from'))$q->whereDate('order_date','>=',$r->date('date_from'));if($r->filled('date_to'))$q->whereDate('order_date','<=',$r->date('date_to'));return $q->latest('order_date')->latest('created_at');}
 public function index(Request $r){$this->authorize($r,'sales.manage');return response()->json(['data'=>$this->query($r)->paginate(min(max($r->integer('per_page',25),10),100))]);}
 public function summary(Request $r){$this->authorize($r,'sales.manage');$q=$this->query($r);$count=fn($s)=>(clone $q)->where('state',$s)->count();return response()->json(['data'=>['total'=>(clone $q)->count(),'draft'=>$count('draft'),'pending_approval'=>$count('pending_approval'),'confirmed'=>$count('confirmed'),'on_hold'=>$count('on_hold'),'backordered'=>(clone $q)->where('reservation_status','partial')->count()]]);}
 public function show(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);return response()->json(['data'=>$order->load(['customer','customerContact','quotation','assignedSalesperson','items.variant.product','items.reservations.location.warehouse','statusHistory.actor'])]);}
 public function store(Request $r){$this->authorize($r,'sales.manage');$d=$this->validated($r);$this->scope($d,$r);$t=$this->tenant();$this->refs($d,$t);$calc=app(\App\Services\SalesCalculationService::class);$lines=array_map(fn($i)=>$calc->line(['quantity'=>$i['ordered_quantity'],'unit_price'=>$i['unit_price'],'discount_rate'=>$i['discount_rate']??0,'tax_rate'=>$i['tax_rate']??0]),$d['items']);$totals=$calc->totals($lines);$o=DB::transaction(function()use($d,$lines,$totals,$t,$r){$o=SalesOrder::create([...$totals,'tenant_id'=>$t,'company_id'=>$d['company_id'],'branch_id'=>$d['branch_id']??null,'currency_id'=>$d['currency_id']??null,'exchange_rate'=>(string)($d['exchange_rate']??'1'),'base_total'=>Decimal::mul((string)$totals['total'],(string)($d['exchange_rate']??'1')),'customer_id'=>$d['customer_id'],'customer_contact_id'=>$d['customer_contact_id']??null,'quotation_id'=>$d['quotation_id']??null,'assigned_salesperson_id'=>$d['assigned_salesperson_id']??null,'created_by'=>$r->user()->id,'number'=>app(\App\Services\SalesNumberService::class)->next($t,'order'),'order_date'=>$d['order_date']??now()->toDateString(),'requested_delivery_date'=>$d['requested_delivery_date']??null,'customer_reference'=>$d['customer_reference']??null,'shipping_address'=>$d['shipping_address']??null,'billing_address'=>$d['billing_address']??null,'shipping_method'=>$d['shipping_method']??null,'delivery_instructions'=>$d['delivery_instructions']??null,'payment_terms'=>$d['payment_terms']??null,'internal_notes'=>$d['internal_notes']??null,'backorder_policy'=>$d['backorder_policy']??'reject','reservation_status'=>'not_reserved','fulfillment_status'=>'not_fulfilled','payment_status'=>'unpaid','state'=>'draft']);foreach($d['items'] as $k=>$i)SalesOrderItem::create([...$lines[$k],'tenant_id'=>$t,'sales_order_id'=>$o->id,'variant_id'=>$i['variant_id'],'preferred_location_id'=>$i['preferred_location_id']??null,'warehouse_id'=>$i['warehouse_id']??null,'description'=>$i['description']??null,'unit'=>$i['unit']??null,'discount_type'=>$i['discount_type']??'percentage','tax_code'=>$i['tax_code']??null,'ordered_quantity'=>$lines[$k]['quantity'],'reserved_quantity'=>'0','backordered_quantity'=>'0']);$this->history($o,null,'draft',$r,'state','Order created');return $o;});return response()->json(['data'=>$o->load('items')],201);}
 public function update(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);abort_unless($order->state==='draft',422,'Only draft orders can be edited.');$d=$this->validated($r);$this->scope($d,$r);$this->refs($d,$this->tenant());$calc=app(\App\Services\SalesCalculationService::class);$lines=array_map(fn($i)=>$calc->line(['quantity'=>$i['ordered_quantity'],'unit_price'=>$i['unit_price'],'discount_rate'=>$i['discount_rate']??0,'tax_rate'=>$i['tax_rate']??0]),$d['items']);$totals=$calc->totals($lines);DB::transaction(function()use($order,$d,$lines,$totals,$r){$order->update([...$totals,'company_id'=>$d['company_id'],'branch_id'=>$d['branch_id']??null,'customer_id'=>$d['customer_id'],'customer_contact_id'=>$d['customer_contact_id']??null,'requested_delivery_date'=>$d['requested_delivery_date']??null,'customer_reference'=>$d['customer_reference']??null,'backorder_policy'=>$d['backorder_policy']??'reject']);$order->items()->delete();foreach($d['items'] as $k=>$i)SalesOrderItem::create([...$lines[$k],'tenant_id'=>$order->tenant_id,'sales_order_id'=>$order->id,'variant_id'=>$i['variant_id'],'preferred_location_id'=>$i['preferred_location_id']??null,'warehouse_id'=>$i['warehouse_id']??null,'description'=>$i['description']??null,'ordered_quantity'=>$lines[$k]['quantity'],'reserved_quantity'=>'0','backordered_quantity'=>'0']);$this->history($order,'draft','draft',$r,'revision','Draft updated');});return response()->json(['data'=>$order->fresh('items')]);}
 public function submit(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);abort_unless($order->state==='draft',422);$order->update(['state'=>'pending_approval']);$this->history($order,'draft','pending_approval',$r);return response()->json(['data'=>$order->fresh()]);}
 public function approve(Request $r,SalesOrder $order){$this->authorize($r,'sales.approve',$order);return $this->reserveAndConfirm($r,$order);}
 public function confirm(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);$out=DB::transaction(function()use($r,$order){$o=SalesOrder::whereKey($order->id)->where('tenant_id',$this->tenant())->lockForUpdate()->firstOrFail();abort_unless(in_array($o->state,['draft','pending_approval','approved','on_hold'],true),422);$partial=false;foreach($o->items()->lockForUpdate()->get() as $i){$ref="sales-order:{$o->id}:{$i->id}";$existing=StockReservation::where('tenant_id',$o->tenant_id)->where('source_reference',$ref)->where('state','active')->lockForUpdate()->first();$already=(string)($existing?->quantity??'0');$need=Decimal::sub((string)$i->ordered_quantity,$already);if(Decimal::compare($need,'0')<=0)continue;$loc=$i->preferred_location_id;if(!$loc)throw ValidationException::withMessages(['items'=>['Every stocked line needs a preferred stock location before confirmation.']]);$b=InventoryBalance::where('tenant_id',$o->tenant_id)->where('variant_id',$i->variant_id)->where('location_id',$loc)->lockForUpdate()->first();$available=$b?Decimal::sub((string)$b->quantity,(string)$b->reserved_quantity):'0';if(Decimal::compare($available,$need)<0){if($o->backorder_policy!=='partial')throw ValidationException::withMessages(['stock'=>['Insufficient available stock for order confirmation.']]);$reserve=$available;$partial=true;}else $reserve=$need;if(Decimal::compare($reserve,'0')>0){abort_unless($b,422);$b->update(['reserved_quantity'=>Decimal::add((string)$b->reserved_quantity,$reserve)]);if($existing)$existing->update(['quantity'=>Decimal::add($already,$reserve),'reserved_at'=>now(),'released_at'=>null]);else StockReservation::create(['tenant_id'=>$o->tenant_id,'company_id'=>$o->company_id,'branch_id'=>$o->branch_id,'sales_order_id'=>$o->id,'sales_order_item_id'=>$i->id,'location_id'=>$loc,'quantity'=>$reserve,'state'=>'active','source_reference'=>$ref,'reserved_at'=>now()]);}$i->update(['reserved_quantity'=>Decimal::add($already,$reserve),'backordered_quantity'=>Decimal::sub((string)$i->ordered_quantity,Decimal::add($already,$reserve))]);}$from=$o->state;$o->update(['state'=>'confirmed','reservation_status'=>$partial?'partial':'reserved','confirmed_by'=>$r->user()->id,'confirmed_at'=>now()]);$this->history($o,$from,'confirmed',$r);return $o;});return response()->json(['data'=>$out->load('items')]);}
 public function availability(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);$rows=$order->load('items.variant.product')->items->map(function($i)use($order){$q=InventoryBalance::where('inventory_balances.tenant_id',$order->tenant_id)->join('warehouse_locations','warehouse_locations.id','=','inventory_balances.location_id')->join('warehouses','warehouses.id','=','warehouse_locations.warehouse_id')->where('warehouses.tenant_id',$order->tenant_id)->where('warehouses.company_id',$order->company_id)->when($order->branch_id,fn($x)=>$x->where('warehouses.branch_id',$order->branch_id));if($i->preferred_location_id)$q->where('inventory_balances.location_id',$i->preferred_location_id);$a=$q->selectRaw('COALESCE(SUM(inventory_balances.quantity-inventory_balances.reserved_quantity),0) available')->value('available')??0;return ['item_id'=>$i->id,'variant'=>$i->variant,'requested_quantity'=>$i->ordered_quantity,'available_quantity'=>(string)$a,'shortage'=>Decimal::compare((string)$a,(string)$i->ordered_quantity)<0?Decimal::sub((string)$i->ordered_quantity,(string)$a):'0'];});return response()->json(['data'=>['items'=>$rows,'can_fulfill'=>$rows->every(fn($x)=>Decimal::compare($x['shortage'],'0')===0)]]);}
 public function reservations(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);return response()->json(['data'=>$order->reservations()->with(['item.variant','location.warehouse'])->get()]);}
 public function activity(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);return response()->json(['data'=>$order->statusHistory()->with('actor')->latest()->get()]);}
 public function pdf(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);return response()->view('sales.order', ['order'=>$order->load(['customer','items.variant.product'])]);}
 public function hold(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);abort_unless(in_array($order->state,['draft','confirmed'],true),422);$from=$order->state;$order->update(['state'=>'on_hold','hold_reason'=>$r->string('reason')->toString()]);$this->history($order,$from,'on_hold',$r,'state',$order->hold_reason);return response()->json(['data'=>$order->fresh()]);}
 public function releaseHold(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);abort_unless($order->state==='on_hold',422);$order->update(['state'=>'confirmed','hold_reason'=>null]);$this->history($order,'on_hold','confirmed',$r);return response()->json(['data'=>$order->fresh()]);}
 public function cancel(Request $r,SalesOrder $order){$this->authorize($r,'sales.manage',$order);$o=DB::transaction(function()use($r,$order){$o=SalesOrder::whereKey($order->id)->lockForUpdate()->firstOrFail();abort_unless(!in_array($o->state,['fulfilled','cancelled'],true),422);foreach($o->reservations()->where('state','active')->lockForUpdate()->get() as $res){$item=$o->items()->whereKey($res->sales_order_item_id)->first();$b=InventoryBalance::where('tenant_id',$o->tenant_id)->where('variant_id',$item?->variant_id)->where('location_id',$res->location_id)->lockForUpdate()->first();if($b)$b->update(['reserved_quantity'=>Decimal::sub((string)$b->reserved_quantity,(string)$res->quantity)]);$res->update(['state'=>'released','released_at'=>now()]);}$from=$o->state;$o->update(['state'=>'cancelled','reservation_status'=>'released']);$this->history($o,$from,'cancelled',$r);return $o;});return response()->json(['data'=>$o->load('items')]);}
 private function validated(Request $r):array{return $r->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','currency_id'=>'nullable|uuid','exchange_rate'=>'nullable|numeric|gt:0','customer_id'=>'required|uuid','customer_contact_id'=>'nullable|uuid','quotation_id'=>'nullable|uuid','assigned_salesperson_id'=>'nullable|uuid','order_date'=>'nullable|date','requested_delivery_date'=>'nullable|date','customer_reference'=>'nullable|string|max:120','shipping_address'=>'nullable|string','billing_address'=>'nullable|string','shipping_method'=>'nullable|string|max:120','delivery_instructions'=>'nullable|string','payment_terms'=>'nullable|string','internal_notes'=>'nullable|string','backorder_policy'=>'nullable|in:reject,partial','items'=>'required|array|min:1','items.*.variant_id'=>'required|uuid','items.*.preferred_location_id'=>'nullable|uuid','items.*.warehouse_id'=>'nullable|uuid','items.*.description'=>'nullable|string','items.*.unit'=>'nullable|string|max:30','items.*.ordered_quantity'=>'required|numeric|gt:0','items.*.unit_price'=>'required|numeric|min:0','items.*.discount_type'=>'nullable|in:percentage,fixed','items.*.discount_rate'=>'nullable|numeric|min:0|max:100','items.*.tax_rate'=>'nullable|numeric|min:0|max:100','items.*.tax_code'=>'nullable|string|max:50']);}
 private function refs(array $d,string $t):void{abort_unless(Customer::where('tenant_id',$t)->where('company_id',$d['company_id'])->whereKey($d['customer_id'])->exists(),404);if(!empty($d['customer_contact_id']))abort_unless(CustomerContact::where('tenant_id',$t)->where('customer_id',$d['customer_id'])->whereKey($d['customer_contact_id'])->exists(),404);foreach($d['items'] as $i){abort_unless(ProductVariant::where('tenant_id',$t)->whereKey($i['variant_id'])->exists(),404);if(!empty($i['warehouse_id']))abort_unless(Warehouse::where('tenant_id',$t)->where('company_id',$d['company_id'])->whereKey($i['warehouse_id'])->exists(),404);if(!empty($i['preferred_location_id']))abort_unless(WarehouseLocation::where('tenant_id',$t)->whereKey($i['preferred_location_id'])->when(!empty($i['warehouse_id']),fn($q)=>$q->where('warehouse_id',$i['warehouse_id']))->exists(),404);}}
}
